function finishEdit(){if(!editing.value)return;const {id,text,target}=editing.value;editing.value=null;if(text.trim())target==='label'?emit('edge-label',id,text.trim()):emit('label',id,text.trim())}
function editKey(e:KeyboardEvent){if(e.key==='Escape'){editing.value=null;e.preventDefault()}else if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();finishEdit()}}
function spaceDown(e:KeyboardEvent){if(e.key==='Escape'){cancel();space.value=false;return}if(e.shiftKey&&!(e.target as Element).closest('input,textarea,select,[contenteditable]')){if(e.code==='Digit1'){fit();e.preventDefault()}if(e.code==='Digit2'){fitSelection();e.preventDefault()}}if(e.code==='Space'&&!(e.target as Element).closest('input,textarea,select,[contenteditable]')){space.value=true;e.preventDefault()}}
function spaceUp(e:KeyboardEvent){if(e.code==='Space')space.value=false}
watch([()=>props.document.id,()=>props.document.presentation.orientation],()=>{editing.value=null;cancel();nextTick(initialView)})
let observer:ResizeObserver,viewportSize:{width:number;height:number}|undefined
function releaseSpace(){space.value=false;cancel()}
onMounted(()=>{initialView();viewportSize={width:viewport.value!.clientWidth,height:viewport.value!.clientHeight};observer=new ResizeObserver(([entry])=>{const {width,height}=entry.contentRect;if(viewportSize){pan.value={x:pan.value.x+(width-viewportSize.width)/2,y:pan.value.y+(height-viewportSize.height)/2}}viewportSize={width,height}});observer.observe(viewport.value!);window.addEventListener('keydown',spaceDown);window.addEventListener('keyup',spaceUp);window.addEventListener('blur',releaseSpace)})
onUnmounted(()=>{observer?.disconnect();window.removeEventListener('keydown',spaceDown);window.removeEventListener('keyup',spaceUp);window.removeEventListener('blur',releaseSpace)})
function centerPoint():Point{const r=viewport.value!.getBoundingClientRect();return world({clientX:r.left+r.width/2,clientY:r.top+r.height/2})}
function contextMenu(e:MouseEvent){const id=(e.target as Element).closest('[data-node-id]')?.getAttribute('data-node-id');if(id)emit('select','node',id);else emit('clear');emit('context-menu',{x:e.clientX,y:e.clientY},world(e))}
defineExpose({fit,initialView,fitSelection,zoom,beginEdit,beginLabelEdit,centerPoint})
</script>
